class Gradebook:
    def __init__(self) -> None:
        self._assignments: dict[str, dict] = {}
        self._grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        if kind not in ("homework", "quiz"):
            raise ValueError(f"invalid kind: {kind!r}")
        if weight < 0:
            raise ValueError(f"weight must be non-negative: {weight!r}")
        if name in self._assignments:
            raise ValueError(f"assignment {name!r} already exists")
        self._assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"unknown assignment: {assignment!r}")
        if not (2.0 <= grade <= 5.0):
            raise ValueError(f"grade out of range [2.0, 5.0]: {grade!r}")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        if not self._assignments:
            return 2.0

        grades_for_student = self._grades.get(student, {})

        # Determine quiz grades to potentially drop (lowest if >1).
        quiz_names = [n for n, a in self._assignments.items() if a["kind"] == "quiz"]
        if not quiz_names:
            drop_quiz = None
        else:
            # A quiz without a recorded grade counts as 2.0.
            quiz_grades = {
                n: grades_for_student.get(n, 2.0) for n in quiz_names
            }
            # Drop lowest if more than one quiz exists.
            if len(quiz_names) > 1:
                drop_quiz = min(quiz_grades, key=lambda n: quiz_grades[n])
            else:
                drop_quiz = None

        total_weight = 0.0
        weighted_sum = 0.0
        for name, info in self._assignments.items():
            if name == drop_quiz:
                continue
            grade = grades_for_student.get(name, 2.0)
            weighted_sum += grade * info["weight"]
            total_weight += info["weight"]

        if total_weight == 0:
            return 2.0
        return round(weighted_sum / total_weight, 2)
